import{canonicalFirm}from'./core.mjs';
const cents=n=>Math.round(Number(n||0)*100);
export function projectTotals(projectRows,subRows){const map=new Map();for(const r of projectRows){if(Number(r.binding)!==1)continue;const t=map.get(r.project)||{project:r.project,ownCents:0,subCents:0,totalCents:0,costCents:0,missingCost:false,hasNuData:false};const v=cents(r.revenue_eur);t.totalCents+=v;if(r.source==='own')t.ownCents+=v;else if(r.source==='sub'){t.subCents+=v;t.hasNuData=true;}map.set(r.project,t)}for(const r of subRows){if(Number(r.binding)!==1)continue;const t=map.get(r.project)||{project:r.project,ownCents:0,subCents:0,totalCents:0,costCents:0,missingCost:false,hasNuData:false};t.hasNuData=true;if(r.cost_eur==null)t.missingCost=true;else t.costCents+=cents(r.cost_eur);map.set(r.project,t)}return[...map.values()].sort((a,b)=>b.totalCents-a.totalCents);}
export function validateRead(raw){const reports=[];for(const[month,m]of Object.entries(raw.months||{})){const subs=(raw.views?.v_sub_day||[]).filter(r=>r.day.startsWith(month)&&Number(r.binding)===1),ps=(raw.views?.v_project_day||[]).filter(r=>r.day.startsWith(month)&&Number(r.binding)===1),projects=projectTotals(ps,subs),ownCents=projects.reduce((a,r)=>a+r.ownCents,0),subCents=projects.reduce((a,r)=>a+r.subCents,0),costCents=projects.reduce((a,r)=>a+r.costCents,0),summaryTotal=cents(m.summary?.sumRevenueEur??m.summary?.revenueEur),companyCost=(m.subs||[]).reduce((a,r)=>a+cents(r.costEur),0);reports.push({month,subRows:subs.length,projectRows:ps.length,ownCents,subCents,totalCents:ownCents+subCents,costCents,revenueMatchesSummary:ownCents+subCents===summaryTotal,companyCostCents:companyCost,companyCostDiffCents:companyCost-costCents,firstDay:ps.length?ps.map(r=>r.day).sort()[0]:null,lastDay:ps.length?ps.map(r=>r.day).sort().at(-1):null});}return reports;}
export function importedSubRows(raw){return(raw.views?.v_sub_day||[]).filter(r=>Number(r.binding)===1).map(r=>({...r,firm:canonicalFirm(r.firm)}));}
export function removeLegacyExtensions(source){const s=structuredClone(source);const autoIds=new Set((s.workers||[]).filter(w=>w.id==='alex-worker').map(w=>w.id));const affected=new Set();const demoIds=new Set(['k1','k2','r1','r2']);s.rows=(s.rows||[]).filter(r=>{const originalHours=r.project?.includes('MIP')?[8,8,8.5,8,7,0,0]:[10,10,10,10,9,0,0];const key=`${r.week}|${r.project}|${r.companyId}`;const untouchedDemo=demoIds.has(r.workerId)&&['2026-W46','2026-W47'].includes(r.week)&&JSON.stringify(r.hours)===JSON.stringify(originalHours)&&!r.userEntered&&!r.dayStatus?.includes('manual')&&!s.approvals?.[key]&&!s.invoiceReviews?.[key];const remove=autoIds.has(r.workerId)||untouchedDemo;if(remove||(r.travelHours||[]).some(Boolean))affected.add(`${r.week}|${r.project}|${r.companyId}`);return !remove}).map(r=>{for(const key of ['travelHours','dayStatus','daySource','sourceProjectId','imported'])delete r[key];return r});s.workers=(s.workers||[]).filter(w=>!autoIds.has(w.id)&&(!demoIds.has(w.id)||w.name||w.assessment||s.rows.some(r=>r.workerId===w.id)||(s.docs||[]).some(d=>d.workerId===w.id&&!d.demo)));s.docs=(s.docs||[]).filter(d=>!d.demo);for(const c of s.companies||[])for(const k of ['selfEmployed','sourceResourceId','sourceLabel'])delete c[k];for(const w of s.workers||[])delete w.sourceResourceId;s.teams=(s.teams||[]).filter(t=>t.id!=='team-'+t.companyId||s.workers.some(w=>w.teamId===t.id));for(const d of s.docs||[])if(autoIds.has(d.workerId))d.workerId='';for(const k of affected){if(s.approvals)delete s.approvals[k];if(s.invoiceReviews?.[k])s.invoiceReviews[k].needsRecheck=true;}for(const key of ['foremanMonths','v2'])delete s[key];return s;}
export const hasRecordedHours=row=>Array.isArray(row.hours)&&row.hours.some(h=>Number.isFinite(Number(h))&&Number(h)>0);
export function groupedHours(rows,week,project='',companyId=''){const groups=new Map();for(const r of rows){if(r.week!==week||(project&&r.project!==project)||(companyId&&r.companyId!==companyId)||!hasRecordedHours(r))continue;const key=r.project+'|'+r.companyId;if(!groups.has(key))groups.set(key,{project:r.project,companyId:r.companyId,rows:[]});groups.get(key).rows.push(r);}return[...groups.values()].sort((a,b)=>a.project.localeCompare(b.project,'de')||a.companyId.localeCompare(b.companyId));}
